# Analyze test clue rows under candidate periods; used to select discriminating period ambiguity.
clues={0:5,4:3,20:7}
for p in range(2,15):
    m={}; ok=True
    for r,c in clues.items():
        k=r%p
        if k in m and m[k]!=c: ok=False
        m[k]=c
    if ok: print(p, sorted(m.items()))
